describe('Mobile Full-Screen Modals on Small Viewports', () => {
  beforeEach(() => {
    cy.visit('/modals');
  });

  it('should display modal in full-screen on small viewports', () => {
    // Set viewport to small size
    cy.viewport('iphone-x');

    // Intercept modal API call
    cy.intercept('GET', '/api/modal/details').as('getModalDetails');

    // Click modal trigger button
    cy.get('[data-testid="modal-trigger"]').click();

    // Wait for modal API call
    cy.wait('@getModalDetails');

    // Verify modal is visible and full-screen
    cy.get('[data-testid="modal-overlay"]').should('be.visible');
    cy.get('[data-testid="modal-content"]').should('be.visible');
    cy.get('[data-testid="modal-content"]').should('have.css', 'width', '100%');
    cy.get('[data-testid="modal-content"]').should('have.css', 'height', '100%');

    // Verify modal has correct title
    cy.get('[data-testid="modal-title"]').should('contain', 'Modal Title');

    // Verify modal has correct body content
    cy.get('[data-testid="modal-body"]').should('contain', 'Modal body content');

    // Verify close button is present
    cy.get('[data-testid="modal-close-btn"]').should('be.visible');

    // Close modal
    cy.get('[data-testid="modal-close-btn"]').click();

    // Verify modal is closed
    cy.get('[data-testid="modal-overlay"]').should('not.exist');
  });

  it('should handle modal closing on small viewports with backdrop click', () => {
    // Set viewport to small size
    cy.viewport('iphone-x');

    // Intercept modal API call
    cy.intercept('GET', '/api/modal/details').as('getModalDetails');

    // Click modal trigger button
    cy.get('[data-testid="modal-trigger"]').click();

    // Wait for modal API call
    cy.wait('@getModalDetails');

    // Verify modal is visible and full-screen
    cy.get('[data-testid="modal-overlay"]').should('be.visible');
    cy.get('[data-testid="modal-content"]').should('be.visible');

    // Verify modal has correct title
    cy.get('[data-testid="modal-title"]').should('contain', 'Modal Title');

    // Verify modal has correct body content
    cy.get('[data-testid="modal-body"]').should('contain', 'Modal body content');

    // Verify close button is present
    cy.get('[data-testid="modal-close-btn"]').should('be.visible');

    // Click backdrop to close modal
    cy.get('[data-testid="modal-overlay"]').click();

    // Verify modal is closed
    cy.get('[data-testid="modal-overlay"]').should('not.exist');

    // Verify page content is still visible
    cy.get('[data-testid="page-content"]').should('be.visible');
  });
});
